function M.refresh_all(on_done)
  local fetcher = require("github_stats.fetcher")

  fetcher.fetch_all(true, function()
    vim.schedule(function()
      if on_done then
        on_done()
      end
    end)
  end)
end

function M.setup_resize_handler(state)
  if not state.buffer or not api.nvim_buf_is_valid(state.buffer) then
    return
  end

  -- Create autocmd for window resize
  api.nvim_create_autocmd("VimResized", {
    buffer = state.buffer,
    callback = function()
      if state and state.is_open then
        local renderer = require("github_stats.dashboard.renderer")
        -- Re-render on resize
        vim.schedule(function()
          pcall(function()
            renderer.render(state)
          end)
        end)
      end
    end,
  })
end

local function fit_width(str, width)
  if #str >= width then
    return str:sub(1, width)
  end
  return str .. string.rep(" ", width - #str)
end

local function fetch_repo_stats(repo, time_range)
  local stats_clones, _ = analytics.query_metric({
    repo = repo,
    metric = "clones",
    time_range = time_range,
  })

  local stats_views, _ = analytics.query_metric({
    repo = repo,
    metric = "views",
    time_range = time_range,
  })

  local trend = compute_trend(stats_clones and stats_clones.daily_breakdown or {})

  return { clones = stats_clones, views = stats_views, trend = trend }
end

