function M.format_bytes(bytes)
  if bytes >= 1024 * 1024 then
    return str_format("%.2f MB", bytes / (1024 * 1024))
  elseif bytes >= 1024 then
    return str_format("%.1f KB", bytes / 1024)
  end
  return str_format("%d B", bytes)
end

